pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount, address target) public {
        vm.assume(actor != address(0) && target != address(0));
        vm.assume(amount > 0);
        // Ensure the actor is not the deployer (owner) to isolate the non-owner case
        vm.assume(actor != address(this));
        // Fund the actor so they can attempt a sendMoney call
        vm.deal(actor, amount);
        // Record target balance before the call
        uint256 beforeBal = target.balance;
        // Simulate a prior owner deposit to the target so that the reference sendMoney can change target balance only if owner calls.
        // However, here we test: after a non-owner calls sendMoney, the target balance must not increase beyond the beforeBal.
        vm.prank(actor);
        try c.sendMoney(target, amount) {} catch {}
        // After the call (whether it reverted or succeeded), check the public state:
        // The reference contract, requiring onlyOwner, should revert for non-owner.
        // The buggy contract allows the call, thus target.balance would increase.
        // Our property: target.balance == beforeBal must hold for the reference.
        // For the bug, target.balance > beforeBal for some input, so the assert will fail.
        assertEq(target.balance, beforeBal, "Bug: non-owner should not be able to increase target balance via sendMoney");
    }
}

