contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint8 ownerSeed) public {
        // 1. restrict depositAmount to avoid overflow and keep ownerSeed non-zero to derive a valid owner
        vm.assume(depositAmount > 0 && depositAmount <= address(c).balance + 1);
        vm.assume(ownerSeed > 0);
        address ownerAddr = address(uint160(uint256(keccak256(abi.encode(ownerSeed)))));
        vm.assume(ownerAddr != address(0) && ownerAddr != address(this) && ownerAddr != address(c));

        // 2. setup: owner deposits Ether via fallback (increases depositsCount and contract balance)
        vm.deal(ownerAddr, depositAmount);
        vm.prank(ownerAddr);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // record state before withdrawAll
        uint256 depositsBefore = c.depositsCount();
        uint256 balanceBefore = address(c).balance;

        // 3. owner calls withdrawAll
        vm.prank(ownerAddr);
        c.withdrawAll();

        // 4. assertTrue: general rule that the reference holds for every admissible input
        //    After withdrawAll, depositsCount is unchanged (no new fallback call),
        //    AND the contract balance becomes the balance before minus any deposits made by a non-owner?
        //    Since the only depositor is the owner, the owner can withdraw everything, so balance becomes 0.
        //    The buggy version does not transfer funds, so balance remains unchanged.
        assertTrue(c.depositsCount() == depositsBefore && address(c).balance == 0);
    }
}

